  ('hi', 'mods.protocol.hint', $json$"सर्वर जिस API फ़ॉर्मेट का इस्तेमाल करता है: OpenAI-संगत, Anthropic, OpenAI Responses या Manus टास्क।"$json$::jsonb),
  ('ar', 'mods.protocol.hint', $json$"صيغة API التي يستخدمها الخادم: متوافقة مع OpenAI أو Anthropic أو OpenAI Responses أو مهام Manus."$json$::jsonb),
