  ('en', 'mods.modelField.hint', $json$"The request field that carries the model. Leave empty for model; Perplexity uses preset."$json$::jsonb),
  ('pt-BR', 'mods.modelField.hint', $json$"O campo do pedido que leva o modelo. Deixe vazio para model; o Perplexity usa preset."$json$::jsonb),
  ('es', 'mods.modelField.hint', $json$"El campo de la solicitud que lleva el modelo. Déjalo vacío para model; Perplexity usa preset."$json$::jsonb),
  ('zh-CN', 'mods.modelField.hint', $json$"请求中携带模型的字段。留空即为 model；Perplexity 使用 preset。"$json$::jsonb),
  ('hi', 'mods.modelField.hint', $json$"अनुरोध का वह फ़ील्ड जिसमें मॉडल जाता है। model के लिए खाली छोड़ें; Perplexity preset इस्तेमाल करता है।"$json$::jsonb),
  ('ar', 'mods.modelField.hint', $json$"حقل الطلب الذي يحمل النموذج. اتركه فارغًا ليكون model؛ ويستخدم Perplexity ‏preset."$json$::jsonb),
  ('fr', 'mods.modelField.hint', $json$"Le champ de la demande qui porte le modèle. Laissez vide pour model ; Perplexity utilise preset."$json$::jsonb),
  ('ru', 'mods.modelField.hint', $json$"Поле запроса, в котором передаётся модель. Оставьте пустым для model; Perplexity использует preset."$json$::jsonb),
  ('ja', 'mods.modelField.hint', $json$"モデルを渡すリクエストのフィールドです。空欄なら model になります。Perplexity は preset を使います。"$json$::jsonb),
